def four_sum_count(nums1, nums2, nums3, nums4):
    sum_counts = {}
    for a in nums1:
        for b in nums2:
            sum_counts[a + b] = sum_counts.get(a + b, 0) + 1

    total = 0
    for c in nums3:
        for d in nums4:
            total += sum_counts.get(-(c + d), 0)

    return total

